@dataclass
class ShiftRosterSchedulerEntity04:
    """Data transfer object for Staff Shift Roster Planning and Overtime Hours Calculator - Segment 4."""
    entity_id: str = field(default_factory=lambda: str(uuid.uuid4()))
    restaurant_code: str = "REST-IND-001"
